            };
            let Some((_, param_ty)) = sig.params.get(index) else {
                continue;
            };
            if matches!(
                param_ty,
                PhpType::Array(_) | PhpType::AssocArray { .. }
            ) {
                env.insert(variable.clone(), param_ty.clone());
            }
        }
    }
}"""
new2 = """        Self::apply_by_ref_array_arg_types(&sig, args, env);
    }
}"""
assert s.count(old2)==1
open(p,'w').write(s.replace(old2,new2))
print('method widening helpers added')
